{
  "schemaVersion": "scene-document/v2",
  "visualDecision": {
    "mode": "scene",
    "reason": "The given points determine the shared graph of both equations."
  },
  "source": {
    "question": "For real x,y, consider L1: 3(x - 2y) + 4 = 2x - y + 9 and L2: -2x + 10y = -10. Graph both equations and label L1 and L2, even if they share the same geometric line. Mark P = (0,-1), Q = (5,0), R = (0,0), and identify which solve BOTH equations. State the full solution set and whether the system determines a unique x-coordinate."
  },
  "quantities": [
    {"id": "px", "symbol": "x_P", "value": 0},
    {"id": "py", "symbol": "y_P", "value": -1},
    {"id": "qx", "symbol": "x_Q", "value": 5},
    {"id": "qy", "symbol": "y_Q", "value": 0},
    {"id": "rx", "symbol": "x_R", "value": 0},
    {"id": "ry", "symbol": "y_R", "value": 0},
    {"id": "x", "symbol": "x"},
    {"id": "y", "symbol": "y"}
  ],
  "entities": [
    {"id": "axes", "kind": "axes", "role": "coordinate axes"},
    {"id": "P", "kind": "point", "label": "P"},
    {"id": "Q", "kind": "point", "label": "Q"},
    {"id": "R", "kind": "point", "label": "R"},
    {"id": "commonLine", "kind": "line", "role": "shared graph of L1 and L2"}
  ],
  "constructions": [
    {"id": "makeAxes", "operator": "axes", "inputs": {"xMin": -2, "xMax": 7, "yMin": -2, "yMax": 2}, "outputs": ["axes"]},
    {"id": "makeP", "operator": "point", "inputs": {"x": "px", "y": "py", "coordinateSpace": "world"}, "outputs": ["P"]},
    {"id": "makeQ", "operator": "point", "inputs": {"x": "qx", "y": "qy", "coordinateSpace": "world"}, "outputs": ["Q"]},
    {"id": "makeR", "operator": "point", "inputs": {"x": "rx", "y": "ry", "coordinateSpace": "world"}, "outputs": ["R"]},
    {"id": "makeCommonLine", "operator": "line", "inputs": {"start": "P", "end": "Q"}, "outputs": ["commonLine"]}
  ],
  "relations": [],
  "assertions": [
    {"id": "pOnLine", "predicate": "on", "entities": ["P", "commonLine"], "expected": true, "severity": "fatal"},
    {"id": "qOnLine", "predicate": "on", "entities": ["Q", "commonLine"], "expected": true, "severity": "fatal"},
    {"id": "rOffLine", "predicate": "on", "entities": ["R", "commonLine"], "expected": false, "severity": "fatal"}
  ],
  "annotations": [
    {"id": "labelL1", "kind": "label", "targetIds": ["commonLine"], "text": "L1", "placementIntent": "near one end"},
    {"id": "labelL2", "kind": "label", "targetIds": ["commonLine"], "text": "L2", "placementIntent": "near the other end"},
    {"id": "solution", "kind": "narration", "targetIds": ["commonLine", "P", "Q", "R"], "text": "Both equations reduce to x−5y=5, so their graphs coincide. P and Q solve both; R solves neither. The full solution set is {(x,y)∈ℝ² : x−5y=5} = {(5+5t,t) : t∈ℝ}. The x-coordinate is not unique."}
  ],
  "requiredEntityIds": ["axes", "P", "Q", "R", "commonLine"],
  "revealGroups": [
    {
      "id": "setup",
      "entityIds": ["axes", "P", "Q", "R", "commonLine"],
      "dependsOn": [],
      "narrationCue": "Plot the three given points and label the shared line L1 and L2."
    }
  ],
  "teachingTimeline": [
    {"id": "showSetup", "revealGroupId": "setup"},
    {"id": "explainSolution", "annotationIds": ["solution"]}
  ]
}

